body {
  /* 
   * Font stack: Browser tries each font in order left-to-right.
   * 1. 'Inter' (custom web font)
   * 2. -apple-system, BlinkMacSystemFont (modern macOS/iOS system fonts)
   * 3. 'Segoe UI' (Windows system font)
   * 4. Roboto (Android system font)
   * 5. sans-serif (guaranteed browser default fallback)
   */
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-weight: 400;
}

.editorial-body {
  font-size: 1.125rem; /* 18px */

  /* 
   * Unitless line-height: 1.6 acts as a proportional multiplier (1.6 * current font-size).
   * If a child heading increases font-size to 32px, its line-height scales proportionally
   * to 51.2px instead of remaining locked to a cramped 24px pixel value!
   */
  line-height: 1.6;
  color: #334155;
}

/* Uppercase tracking: wide spacing enhances legibility of all-caps copy */
.meta-badge {
  text-transform: uppercase;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: #64748b;
}

/* Large display headline: slight negative tracking creates punchy visual presence */
.hero-title {
  font-size: 3rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.15;
}
